const P2A_INK = "#4D3854";
const P2A_SOFT = "#7B6A76";
const P2A_GOOD = "#2F9E5B";
const P2A_BLUE = "#3D8BD9";
const P2A_PURPLE = "#8E5BD6";
const P2A_WARN = "#D2455F";

simStyle(`
.cross-read,.pedigree-read,.protein-read{display:grid;grid-template-columns:repeat(auto-fit,minmax(118px,1fr));gap:8px}.cross-tile,.pedigree-tile,.protein-tile{border:2px solid #E6DCD2;border-radius:15px;background:#fff;padding:9px 10px;min-width:0}.cross-tile b,.pedigree-tile b,.protein-tile b{display:block;font-size:.82rem;color:var(--ink-soft)}.cross-big,.pedigree-big,.protein-big{display:block;font-weight:950;font-size:1.22rem;color:var(--ink);line-height:1.15;overflow-wrap:anywhere}.cross-note,.pedigree-note,.protein-note{border-radius:15px;background:#FFF7D6;border:2px dashed #E8CF76;padding:10px 12px;font-weight:800;line-height:1.35}.cross-bank,.pedigree-bank,.protein-bank{display:flex;flex-wrap:wrap;gap:6px}.cross-bank button,.pedigree-bank button,.protein-bank button{min-height:44px;border:2px solid #E6DCD2;border-radius:12px;background:#fff;font-weight:900;color:var(--ink);padding:7px 9px}.cross-bank button[aria-pressed=true],.pedigree-bank button[aria-pressed=true],.protein-bank button[aria-pressed=true]{background:#E6F8EC;border-color:#3FA06B;box-shadow:0 0 0 2px #3FA06B}.cross-punnett{display:grid;grid-template-columns:60px repeat(2,minmax(76px,1fr));gap:6px;align-items:stretch}.cross-punnett span{min-height:48px;border-radius:12px;border:2px solid #E6DCD2;background:#fff;display:grid;place-items:center;text-align:center;font-weight:950;padding:4px;line-height:1.15}.cross-punnett .cross-head{background:#EAF4FF;border-color:#BBD8F5}.cross-punnett .cross-cell.on{background:#F0FFF4;border-color:#3FA06B}.cross-bars,.protein-codons{display:grid;gap:7px}.cross-bar{display:grid;grid-template-columns:minmax(86px,1fr) 1.4fr 54px;gap:6px;align-items:center;font-weight:850}.cross-bar i{display:block;height:18px;border-radius:999px;border:2px solid rgba(77,56,84,.18);background:linear-gradient(90deg,#8EDB8F,#D6F5B8);width:var(--w)}.cross-bar.obs i{background:linear-gradient(90deg,#8E5BD6,#C6A9F7)}.cross-mini{display:grid;grid-template-columns:1fr 1fr;gap:8px}.cross-mini svg{width:100%;height:auto;display:block}.pedigree-hyp{display:grid;grid-template-columns:repeat(auto-fit,minmax(142px,1fr));gap:8px}.pedigree-hyp button{min-height:50px;border:2px solid #E6DCD2;border-radius:14px;background:#fff;font-weight:900;color:var(--ink);padding:8px}.pedigree-hyp button[aria-pressed=true]{background:#F3ECFF;border-color:#8E5BD6;box-shadow:0 0 0 2px #8E5BD6}.pedigree-people{display:grid;grid-template-columns:repeat(auto-fit,minmax(90px,1fr));gap:6px}.pedigree-people button{min-height:48px;border:2px solid #E6DCD2;border-radius:12px;background:#fff;color:var(--ink);font-weight:900;padding:6px}.pedigree-people button.good{background:#E6F8EC;border-color:#3FA06B}.pedigree-people button.bad{background:#FFF0F0;border-color:#D2455F}.pedigree-clues{display:grid;gap:7px}.pedigree-clue{border:2px solid #E6DCD2;border-radius:14px;background:#fff;padding:8px 10px;font-weight:800}.pedigree-clue.on{background:#EAF4FF;border-color:#3D8BD9}.protein-flow{display:grid;grid-template-columns:repeat(auto-fit,minmax(128px,1fr));gap:8px}.protein-node{border:2px solid #E6DCD2;border-radius:14px;background:#fff;padding:9px;text-align:center;font-weight:900;min-height:66px;display:grid;place-items:center}.protein-node.on{background:#E6F8EC;border-color:#3FA06B;box-shadow:0 0 0 2px rgba(63,160,107,.2)}.protein-bases{display:grid;grid-template-columns:repeat(6,minmax(44px,1fr));gap:6px}.protein-bases button{min-height:44px;border:2px solid #D7CBEA;border-radius:12px;background:#fff;font-weight:950;color:var(--ink)}.protein-bases button.on{background:#F3ECFF;border-color:#8E5BD6}.protein-codon{display:grid;grid-template-columns:70px 74px minmax(0,1fr);gap:6px;align-items:center;border:2px solid #E6DCD2;border-radius:12px;padding:6px 8px;background:#fff;font-weight:850}.protein-codon b{font-size:1rem;color:#56358F}.protein-table{display:grid;grid-template-columns:repeat(auto-fit,minmax(92px,1fr));gap:6px}.protein-table span{border-radius:10px;background:#F4EEE8;padding:6px 8px;font-weight:850;text-align:center}.protein-mutrow{display:grid;grid-template-columns:repeat(auto-fit,minmax(132px,1fr));gap:8px}.protein-mutrow button{min-height:48px}.protein-effect{border:2px solid #D7CBEA;border-radius:15px;background:#F8F4FF;padding:9px 10px;font-weight:850}.cross-flash{animation:crossFlash .65s ease-out}.protein-pulse{animation:proteinPulse .8s ease-out}@keyframes crossFlash{50%{transform:scale(1.025);filter:brightness(1.08)}}@keyframes proteinPulse{50%{transform:scale(1.03);filter:brightness(1.08)}}@media(max-width:520px){.cross-punnett{grid-template-columns:48px repeat(2,minmax(64px,1fr))}.cross-punnett span{font-size:.86rem}.cross-mini{grid-template-columns:1fr}.protein-bases{grid-template-columns:repeat(4,minmax(44px,1fr))}.protein-codon{grid-template-columns:54px 62px minmax(0,1fr);font-size:.88rem}}@media(prefers-reduced-motion:reduce){.cross-flash,.protein-pulse{animation:none}}
`);

/* ---------------- 2a-10. 🫛 Genetic crosses ---------------- */
const CROSS_CASES = {
  peaF1: { mode: "pea", label: "P → F1", parents: ["TT", "tt"], parentPhen: ["Tall plant", "Dwarf plant"], alleles: ["T", "t"], note: "Pure-breeding tall × dwarf gives all heterozygous tall F1.", expect: { "Tall": 4, "Dwarf": 0 } },
  peaF2: { mode: "pea", label: "F1 × F1", parents: ["Tt", "Tt"], parentPhen: ["Tall F1", "Tall F1"], alleles: ["T", "t"], note: "F1 selfing shows the 3:1 dominant:recessive phenotype ratio.", expect: { "Tall": 3, "Dwarf": 1 } },
  peaTest: { mode: "test", label: "Test cross", parents: ["T?", "tt"], parentPhen: ["Tall unknown", "Dwarf tester"], alleles: ["T", "t"], note: "Unknown tall × homozygous recessive reveals TT or Tt from the offspring." },
  abo: { mode: "abo", label: "ABO blood", parents: ["AO", "BO"], parentPhen: ["Group A", "Group B"], alleles: ["A", "B", "O"], note: "Iᴬ and Iᴮ are codominant; i is recessive.", expect: { "A": 1, "B": 1, "AB": 1, "O": 1 } },
  sex: { mode: "sex", label: "X-linked", parents: ["XHXh", "XhY"], parentPhen: ["Carrier female", "Affected male"], alleles: ["XH", "Xh", "Y"], note: "Males have one X chromosome, so one recessive Xʰ allele is expressed.", expect: { "Normal female": 1, "Carrier female": 0, "Affected female": 1, "Normal male": 1, "Affected male": 1 } }
};
function crossSup(a) { return String(a).replace(/IA/g, "Iᴬ").replace(/IB/g, "Iᴮ").replace(/XH/g, "Xᴴ").replace(/Xh/g, "Xʰ").replace(/AO/g, "Iᴬi").replace(/BO/g, "Iᴮi").replace(/AA/g, "IᴬIᴬ").replace(/BB/g, "IᴮIᴮ").replace(/AB/g, "IᴬIᴮ").replace(/OO/g, "ii"); }
function crossGametes(g) {
  if (g === "TT") return ["T", "T"]; if (g === "Tt" || g === "tT") return ["T", "t"]; if (g === "tt") return ["t", "t"]; if (g === "T?") return ["T", "?"];
  if (g === "AO") return ["A", "O"]; if (g === "BO") return ["B", "O"]; if (g === "AB") return ["A", "B"]; if (g === "AA") return ["A", "A"]; if (g === "BB") return ["B", "B"]; if (g === "OO") return ["O", "O"];
  if (g === "XHXh") return ["XH", "Xh"]; if (g === "XHY") return ["XH", "Y"]; if (g === "XhY") return ["Xh", "Y"]; if (g === "XHXH") return ["XH", "XH"];
  return ["?", "?"];
}
function crossCombine(a, b, mode) {
  if (mode === "pea" || mode === "test") return (a === "T" || b === "T") ? (a === b ? "TT" : "Tt") : "tt";
  if (mode === "abo") { const s = [a, b].sort().join(""); return s === "AB" ? "AB" : s === "AO" ? "AO" : s === "BO" ? "BO" : s === "AA" ? "AA" : s === "BB" ? "BB" : "OO"; }
  if (mode === "sex") return a.startsWith("X") && b.startsWith("X") ? a + b.replace("X", "X") : a.startsWith("X") ? a + b : b + a;
  return a + b;
}
function crossPhen(gen, mode) {
  if (mode === "pea" || mode === "test") return gen.includes("T") ? "Tall" : "Dwarf";
  if (mode === "abo") return gen === "AB" ? "AB" : gen.includes("A") ? "A" : gen.includes("B") ? "B" : "O";
  if (mode === "sex") {
    if (gen.includes("Y")) return gen.includes("Xh") ? "Affected male" : "Normal male";
    const n = (gen.match(/Xh/g) || []).length; return n === 2 ? "Affected female" : n === 1 ? "Carrier female" : "Normal female";
  }
  return gen;
}
function crossGrid(st) { const c = CROSS_CASES[st.caseId], g1 = crossGametes(c.parents[0]), g2 = crossGametes(c.parents[1]); return g1.map(a => g2.map(b => ({ a, b, gen: crossCombine(a, b, c.mode), phen: crossPhen(crossCombine(a, b, c.mode), c.mode) }))); }
function crossExpected(st) { const c = CROSS_CASES[st.caseId]; if (c.expect) return c.expect; const grid = crossGrid(st), out = {}; grid.flat().forEach(x => out[x.phen] = (out[x.phen] || 0) + 1); return out; }
function crossRand(st) { st.seed = (st.seed * 1664525 + 1013904223) >>> 0; return st.seed / 4294967296; }
function crossBreed(st, n) { const grid = crossGrid(st).flat().filter(x => !x.gen.includes("?")); const out = {}; st.seed = (12781 + n * 97 + st.runs * 211 + st.caseId.length * 17) >>> 0; for (let i = 0; i < n; i++) { const z = grid[Math.floor(crossRand(st) * grid.length)]; out[z.phen] = (out[z.phen] || 0) + 1; } st.obs = out; st.sample = n; st.runs++; }
simReg({ id: "cross", ic: "🫛", name: "Genetic crosses", sec: "2a", ord: 10, topic: "t9", fn: crossSim,
  words: [["allele", "A/a", "one form of a gene"], ["genotype", "🧬", "the alleles an organism has"], ["phenotype", "👁️", "the observable feature"], ["gamete", "⚪", "sex cell carrying one allele"], ["Punnett square", "▦", "grid predicting offspring genotypes"], ["test cross", "🧪", "unknown crossed with homozygous recessive"], ["codominance", "🤝", "both alleles show in the heterozygote"]] });
function crossSim(root) {
  // Alleles segregate into gametes → random fertilisation gives predictable ratios, but small samples show chance.
  const st = { caseId: "peaF1", filled: 0, sample: 0, obs: {}, runs: 0, seed: 1, n: 10, testPattern: "", variation: "none" };
  root.innerHTML = `<div class="simgrid wide"><section class="card"><div id="crossScene" class="simsvg nozoom"></div><div class="simctl"><div><b class="small">Mode</b><div class="cross-bank">${[["peaF1","P → F1"],["peaF2","F1 → F2"],["abo","ABO"],["sex","X-linked"],["peaTest","Test cross"]].map(([k,l])=>`<button data-cross-case="${k}" aria-pressed="${k===st.caseId}">${l}</button>`).join("")}</div></div><div><b class="small">Fill square</b><div class="row simbtns"><button class="btn" id="crossFill">▦ Fill next</button><button class="btn plain" id="crossClear">↺ Clear</button></div></div></div><div id="crossRead" class="cross-read"></div></section><section class="card"><h3 style="margin:0">🎲 Random offspring</h3><div id="crossPunnett" class="cross-punnett"></div><div class="row simbtns"><button class="btn yellow" data-cross-n="10">Breed 10</button><button class="btn" data-cross-n="100">Breed 100</button><button class="btn blue" data-cross-n="1000">Breed 1000</button></div><div id="crossBars" class="cross-bars"></div><div class="cross-note" id="crossWhy"></div></section></div><section class="card"><h3 style="margin:0">🧪 Test cross + variation</h3><div class="simgrid"><div><b class="small">Test-cross observation</b><div class="cross-bank"><button data-cross-test="all" aria-pressed="false">All tall offspring</button><button data-cross-test="half" aria-pressed="false">1:1 tall:dwarf</button></div><p class="small muted" id="crossTestOut">Choose an observation to deduce the unknown genotype.</p></div><div><b class="small">Variation picture</b><div class="cross-bank"><button data-cross-var="discontinuous" aria-pressed="false">ABO bars</button><button data-cross-var="continuous" aria-pressed="false">Height histogram</button></div><div id="crossVar" class="simsvg nozoom"></div></div></div></section>`;
  const draw = () => {
    root.querySelectorAll("[data-cross-case]").forEach(b => b.setAttribute("aria-pressed", b.dataset.crossCase === st.caseId));
    root.querySelectorAll("[data-cross-test]").forEach(b => b.setAttribute("aria-pressed", b.dataset.crossTest === st.testPattern));
    root.querySelectorAll("[data-cross-var]").forEach(b => b.setAttribute("aria-pressed", b.dataset.crossVar === st.variation));
    root.querySelector("#crossScene").innerHTML = crossSceneSvg(st); root.querySelector("#crossRead").innerHTML = crossReadHtml(st); root.querySelector("#crossPunnett").innerHTML = crossPunnettHtml(st); root.querySelector("#crossBars").innerHTML = crossBarsHtml(st); root.querySelector("#crossWhy").innerHTML = crossWhyHtml(st); root.querySelector("#crossVar").innerHTML = crossVariationSvg(st); root.querySelector("#crossTestOut").textContent = st.testPattern === "all" ? "All tall offspring → unknown parent is TT." : st.testPattern === "half" ? "1:1 tall:dwarf offspring → unknown parent is Tt." : "Choose an observation to deduce the unknown genotype.";
  };
  root.querySelectorAll("[data-cross-case]").forEach(b => b.onclick = () => { SFX.tap(); st.caseId = b.dataset.crossCase; st.filled = 0; st.sample = 0; st.obs = {}; draw(); });
  root.querySelector("#crossFill").onclick = () => { SFX.tap(); st.filled = Math.min(4, st.filled + 1); root.querySelector("#crossPunnett").classList.add("cross-flash"); setTimeout(()=>root.querySelector("#crossPunnett")&&root.querySelector("#crossPunnett").classList.remove("cross-flash"), 700); draw(); };
  root.querySelector("#crossClear").onclick = () => { SFX.tap(); st.filled = 0; draw(); };
  root.querySelectorAll("[data-cross-n]").forEach(b => b.onclick = () => { SFX.item(); crossBreed(st, Number(b.dataset.crossN)); draw(); });
  root.querySelectorAll("[data-cross-test]").forEach(b => b.onclick = () => { SFX.tap(); st.caseId = "peaTest"; st.testPattern = b.dataset.crossTest; st.filled = 0; draw(); });
  root.querySelectorAll("[data-cross-var]").forEach(b => b.onclick = () => { SFX.tap(); st.variation = b.dataset.crossVar; draw(); });
  simProbe(() => { const exp = crossExpected(st), total = Object.values(exp).reduce((a,b)=>a+b,0) || 1, obsTot = Object.values(st.obs).reduce((a,b)=>a+b,0) || 0; return { mode: CROSS_CASES[st.caseId].mode, caseId: st.caseId, filled: st.filled, sampleSize: st.sample, runs: st.runs, testPattern: st.testPattern, testDeduction: st.testPattern === "all" ? "TT" : st.testPattern === "half" ? "Tt" : "", variation: st.variation, expectedTallPct: +(((exp.Tall || 0) / total) * 100).toFixed(1), expectedDwarfPct: +(((exp.Dwarf || 0) / total) * 100).toFixed(1), observedTall: st.obs.Tall || 0, observedDwarf: st.obs.Dwarf || 0, observedDominantPct: obsTot ? +(((st.obs.Tall || st.obs.A || 0) / obsTot) * 100).toFixed(1) : 0, aboPossible: Object.keys(exp).sort().join("/"), carrierRiskPct: st.caseId === "sex" ? 50 : 0 }; });
  draw();
}
function crossShortNote(c) { return c.mode === "pea" ? "F1 selfing → 3:1 phenotype ratio." : c.mode === "test" ? "Unknown × tt reveals TT or Tt." : c.mode === "abo" ? "Iᴬ and Iᴮ codominant; i recessive." : "X-linked recessive: males show one Xʰ."; }
function crossSceneSvg(st) { const c = CROSS_CASES[st.caseId], pea = c.mode === "pea" || c.mode === "test"; return `<svg viewBox="0 0 420 250" role="img" aria-label="Genetic cross with parent phenotypes, genotypes and gametes"><rect width="420" height="250" rx="16" fill="#F7FBF0"/><text x="210" y="24" text-anchor="middle" font-size="17" font-weight="950" fill="${P2A_INK}">${c.label}: ${c.parentPhen.join(" × ")}</text>${pea ? crossPeaSvg(32,54,c.parents[0],c.parentPhen[0]) + crossPeaSvg(282,54,c.parents[1],c.parentPhen[1]) : crossPeopleSvg(c)}<text x="210" y="104" text-anchor="middle" font-size="24" font-weight="950" fill="${P2A_PURPLE}">×</text><text x="210" y="143" text-anchor="middle" font-size="13" font-weight="900" fill="${P2A_INK}">Gametes (one allele each)</text>${crossGametes(c.parents[0]).map((g,i)=>`<g><circle cx="${160+i*34}" cy="176" r="15" fill="#fff" stroke="${P2A_INK}" stroke-width="2"/><text x="${160+i*34}" y="181" text-anchor="middle" font-size="13" font-weight="950" fill="${P2A_INK}">${crossSup(g)}</text></g>`).join("")}${crossGametes(c.parents[1]).map((g,i)=>`<g><circle cx="${236+i*34}" cy="176" r="15" fill="#fff" stroke="${P2A_INK}" stroke-width="2"/><text x="${236+i*34}" y="181" text-anchor="middle" font-size="13" font-weight="950" fill="${P2A_INK}">${crossSup(g)}</text></g>`).join("")}<text x="210" y="224" text-anchor="middle" font-size="13" font-weight="900" fill="${P2A_SOFT}">${crossShortNote(c)}</text></svg>`; }
function crossPeaSvg(x,y,gen,lab) { const tall = gen !== "tt"; return `<g transform="translate(${x} ${y})"><path d="M50 118 C48 86 56 52 48 18" stroke="#3D8B3D" stroke-width="6" fill="none" stroke-linecap="round"/><path d="M48 62 C25 48 16 35 14 18 C38 18 52 34 51 55" fill="#6FC06C" stroke="${P2A_INK}" stroke-width="2"/><path d="M51 82 C78 69 94 52 98 31 C70 30 51 50 48 74" fill="#73C778" stroke="${P2A_INK}" stroke-width="2"/><path d="M46 92 C28 84 18 73 14 59 C34 57 48 69 51 88" fill="#7ECD75" stroke="${P2A_INK}" stroke-width="2"/>${[0,1,2].map(i=>`<ellipse cx="${64+i*10}" cy="${44+i*8}" rx="8" ry="17" transform="rotate(55 ${64+i*10} ${44+i*8})" fill="#55A852" stroke="${P2A_INK}" stroke-width="2"/><circle cx="${59+i*10}" cy="${42+i*8}" r="4" fill="#A9E889"/>`).join("")}<line x1="10" x2="106" y1="120" y2="120" stroke="#8B6B3B" stroke-width="4"/><text x="58" y="142" text-anchor="middle" font-size="13" font-weight="950" fill="${P2A_INK}">${lab}</text><text x="58" y="160" text-anchor="middle" font-size="16" font-weight="950" fill="${tall ? P2A_GOOD : P2A_WARN}">${crossSup(gen)}</text></g>`; }
function crossPeopleSvg(c) { return `<g transform="translate(42 58)"><circle cx="48" cy="36" r="25" fill="#FFE2B8" stroke="${P2A_INK}" stroke-width="3"/><path d="M20 94 q28 -36 56 0" fill="#EAF4FF" stroke="${P2A_INK}" stroke-width="3"/><text x="48" y="132" text-anchor="middle" font-size="13" font-weight="950" fill="${P2A_INK}">${c.parentPhen[0]}</text><text x="48" y="151" text-anchor="middle" font-size="15" font-weight="950" fill="${P2A_PURPLE}">${crossSup(c.parents[0])}</text></g><g transform="translate(290 58)"><rect x="21" y="11" width="54" height="54" rx="11" fill="#FFE2B8" stroke="${P2A_INK}" stroke-width="3"/><path d="M20 94 q28 -36 56 0" fill="#F4ECFF" stroke="${P2A_INK}" stroke-width="3"/><text x="48" y="132" text-anchor="middle" font-size="13" font-weight="950" fill="${P2A_INK}">${c.parentPhen[1]}</text><text x="48" y="151" text-anchor="middle" font-size="15" font-weight="950" fill="${P2A_PURPLE}">${crossSup(c.parents[1])}</text></g>`; }
function crossReadHtml(st) { const c = CROSS_CASES[st.caseId], exp = crossExpected(st), tot = Object.values(exp).reduce((a,b)=>a+b,0)||1, ph = Object.entries(exp).map(([k,v])=>`${k} ${v}`).join(" : "); return `<div class="cross-tile"><b>Parents</b><span class="cross-big">${c.parents.map(crossSup).join(" × ")}</span></div><div class="cross-tile"><b>Expected ratio</b><span class="cross-big">${ph}</span></div><div class="cross-tile"><b>Dominant / recessive</b><span class="cross-big">${Math.round(((exp.Tall||0)/tot)*100)}% / ${Math.round(((exp.Dwarf||0)/tot)*100)}%</span></div><div class="cross-tile"><b>Sample</b><span class="cross-big">${st.sample || "not bred"}</span></div>`; }
function crossPunnettHtml(st) { const c = CROSS_CASES[st.caseId], g1 = crossGametes(c.parents[0]), g2 = crossGametes(c.parents[1]), grid = crossGrid(st); return `<span></span>${g2.map(g=>`<span class="cross-head">⚪ ${crossSup(g)}</span>`).join("")}${g1.map((g,i)=>`<span class="cross-head">⚪ ${crossSup(g)}</span>${grid[i].map((z,j)=>{ const k=i*2+j; return `<span class="cross-cell ${st.filled>k?"on":""}">${st.filled>k?`${crossSup(z.gen)}<small>${z.phen}</small>`:"?"}</span>`; }).join("")}`).join("")}`; }
function crossBarsHtml(st) { const exp = crossExpected(st), labels = Object.keys(exp), et = Object.values(exp).reduce((a,b)=>a+b,0)||1, ot = Object.values(st.obs).reduce((a,b)=>a+b,0)||1; return labels.map(k=>`<div class="cross-bar"><span>Expected ${k}</span><i style="--w:${Math.round(exp[k]/et*100)}%"></i><b>${Math.round(exp[k]/et*100)}%</b></div><div class="cross-bar obs"><span>Observed ${k}</span><i style="--w:${Math.round((st.obs[k]||0)/ot*100)}%"></i><b>${st.sample?Math.round((st.obs[k]||0)/ot*100)+"%":"—"}</b></div>`).join(""); }
function crossWhyHtml(st) { return st.sample ? `Observed numbers are chance outcomes. With <b>${st.sample}</b> offspring, the bars usually move closer to the expected probability.` : `Parents → gametes → Punnett square → expected ratio. Then random fertilisation gives actual offspring.`; }
