  colour: { name:"Colour blindness", trait:"X-linked recessive", hyp:"xr", prob:25, clue:"Mostly males affected; a carrier mother can have affected sons.", gen:{"I-1":"XᴴY","I-2":"XᴴXʰ","II-1":"XʰY","II-2":"XᴴXʰ","II-3":"XᴴY"}, people:[ ["I-1","m",0,82,44,"XᴴY"],["I-2","f",0,170,44,"XᴴXʰ",1],["II-1","m",1,82,146,"XʰY"],["II-2","f",0,150,146,"XᴴXʰ",1],["II-3","m",0,216,146,"XᴴY"] ], wrong:{ar:["II-1"], ad:["I-2"], xd:["II-1"]} },
  haem: { name:"Haemophilia", trait:"X-linked recessive", hyp:"xr", prob:50, clue:"Affected father gives Xʰ to all daughters; sons get his Y.", gen:{"I-1":"XʰY","I-2":"XᴴXʰ","II-1":"XʰXʰ","II-2":"XᴴY","II-3":"XʰY"}, people:[ ["I-1","m",1,82,44,"XʰY"],["I-2","f",0,170,44,"XᴴXʰ",1],["II-1","f",1,82,146,"XʰXʰ"],["II-2","m",0,150,146,"XᴴY"],["II-3","m",1,216,146,"XʰY"] ], wrong:{ar:["II-1"], ad:["I-2"], xd:["II-2"]} },
  tongue: { name:"Tongue rolling", trait:"autosomal dominant", hyp:"ad", prob:75, clue:"Everyday traits can be dominant or recessive; environment may affect expression.", gen:{"I-1":"Rr","I-2":"Rr","II-1":"RR/Rr","II-2":"rr","II-3":"Rr"}, people:[ ["I-1","m",1,82,44,"Rr"],["I-2","f",1,170,44,"Rr"],["II-1","f",1,82,146,"RR/Rr"],["II-2","m",0,150,146,"rr"],["II-3","f",1,216,146,"Rr"] ], wrong:{ar:["I-1","I-2"], xr:["II-1"], xd:["II-2"]} }
