  root.querySelector("#proteinTranslate").onclick=()=>{ SFX.item(); st.phase="translate"; st.progress=0; st.ranTransl=true; draw(); };
  root.querySelector("#proteinReset").onclick=()=>{ SFX.tap(); proteinSetMutation(st,"reset"); st.edits=0; draw(); };
  simProbe(()=>{ const m=proteinModel(st); return { template:st.tpl.join(""), mrna:m.mrna, codons:m.cod.join("/"), firstCodon:m.cod[0]||"", secondCodon:m.cod[1]||"", aminoAcids:m.aa.join("-"), aaCount:m.aa.length, stopIndex:m.stop, anticodon1:proteinAnticodon(m.cod[0]||""), anticodon2:proteinAnticodon(m.cod[1]||""), phase:st.phase, progress:+st.progress.toFixed(2), ranTranscription:st.ranTrans, ranTranslation:st.ranTransl, mutation:st.mut, effect:m.effect, frameshift:m.frameshift, length:m.len, edits:st.edits }; });
